import{_ as o,l as i,o as e,c as l,v as r,p as n,x as s,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"目录协议的扩展性","description":"","frontmatter":{"title":"目录协议的扩展性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/directory-scalability.md","filePath":"cs/directory-scalability.md","lastUpdated":1789023840000}'),m={name:"cs/directory-scalability.md"};function p(E,a,_,A,f,u){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="目录协议的扩展性" tabindex="-1">目录协议的扩展性 <a class="header-anchor" href="#目录协议的扩展性" aria-label="Permalink to &quot;目录协议的扩展性&quot;">​</a></h1><div class="epigraph"><p>窥探要求每个缺失让所有 cache 听见；目录记下谁可能有副本，只向那几个节点发点对点请求，流量随共享集而不是随核数涨。</p><footer>—— 据 Censier and Feautrier；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/moesi-mesif">上一课</a> 在广播总线上加了 O/F。核数到几十上百时，即使 F 减少重复数据，<strong>地址事务仍要人人听</strong>。本课不重画五态。缺口是<strong>目录：每行（或每组）一份 sharer 向量 / 指针，把一致性从广播改成端到端。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窥探带宽 ∝ 核数 × miss 率。互连变成广播介质后，<a href="/cs/mlp-memory-parallelism">MLP</a> 越高越堵。缺口不是再加一个 Forward 态，而是<strong>用存储换广播：目录项指出可能的副本集合。</strong> 目录本身要分区到 LLC slice 或 memory controller，否则又成为单点。</p><p><span class="marginnote">完整位向量：每核一位，精确但随核数线性涨。稀疏目录：少量指针，溢出则广播或退化为粗向量。这是面积与无效流量的交易。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 miss：向 home 目录要数据与权限；目录把请求者加入 sharer，若存在 owner 则转发。写 miss：目录向所有 sharer 发 invalidate，收集 ack，再给请求者 M。替换：通知目录删 sharer，脏则写回。</p>',8)),(e(),n(h,null,{default:s(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%A0%B8%20miss%22%5D%20--%3E%20HOME%5B%22%E8%AF%A5%E8%A1%8C%E7%9A%84%E7%9B%AE%E5%BD%95%20home%22%5D%0A%20%20HOME%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E5%88%B0%20owner%20%2F%20%E8%AE%B0%E5%BF%86%E4%BD%93%22%5D%0A%20%20HOME%20--%3E%20INV%5B%22%E7%82%B9%E5%AF%B9%E7%82%B9%E4%BD%9C%E5%BA%9F%20sharer%22%5D%0A%20%20INV%20--%3E%20ACK%5B%22%E6%94%B6%E9%9B%86%20ack%20%E5%86%8D%E6%8E%88%E6%9D%83%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟从「一跳广播」变成「到 home 再可能到 owner」，跳数增加，但带宽可扩展。与 <a href="/cs/moesi-mesif">MOESI</a> 组合：目录里存 owner 指针而不是只存 S 集合。伪共享表现为同一目录项上的频繁 inv，协议正确、性能差。</p><p>目录存储与 LLC 标签可共存（in-cache directory）：行在 LLC 则目录免费，被踢出则要写回或记 overflow。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某种 NoC 拓扑定成唯一 home 映射，后课 mesh 会决定 slice 怎么放。也不处理死锁的虚通道，那是 NoC 路由课。原子与 acquire/release 建立在「行已按目录拿到合适态」之上，随后几课。</p><p>后课默认：大规模用目录；共享集溢出才广播。同一行上无关变量互踢，是下一课伪共享。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目录用 sharer 集合代替广播监听，换存储与多跳延迟。</li><li>home 必须分区，否则单点。</li><li>行粒度上的虚假争用是下一课伪共享。</li><li>出处：Censier and Feautrier；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const b=o(m,[["render",p]]);export{C as __pageData,b as default};
